import {renderOverview,renderStudentHome} from './views.js';
import {seed,stages,metrics,scopedCases,audit,transition,simulateReminder,reminderEligibility,book,cancelBooking,scenarioResult,parseCSV,validateImport} from './model.js';
const $=(q,root=document)=>root.querySelector(q);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tasks:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',calendar:'M4 5h16v16H4z M16 3v4 M8 3v4 M4 10h16 M8 14h2 M14 14h2 M8 17h2',chart:'M4 3v17h17 M8 15v-4 M13 15V7 M18 15v-8',data:'M20 6c0 2-16 2-16 0s16-2 16 0v12c0 3-16 3-16 0V6 M4 12c0 3 16 3 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',arrow:'M5 12h14 M14 7l5 5-5 5',down:'M6 9l6 6 6-6',chevron:'M9 5l7 7-7 7',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',filter:'M4 6h16 M7 12h10 M10 18h4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M21 21v-3a4 4 0 0 0-3-3.87 M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M16 2a4 4 0 0 1 0 8',check:'M5 12l4 4L19 6',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h5',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 18h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',close:'M6 6l12 12 M18 6 6 18',menu:'M4 6h16 M4 12h16 M4 18h16',leaf:'M20 3C5 2 1 10 7 17c7 6 15 2 13-14 M5 20l11-11',home:'M3 10l9-7 9 7v11h-7v-7h-4v7H3z',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0',map:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',book:'M12 5c-4-3-9-2-9-2v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2v16',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 2 M18 18a8 8 0 0 1-13-2',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',mail:'M3 5h18v14H3z M3 5l9 7 9-7',logout:'M9 4H3v16h6 M13 8l4 4-4 4 M7 12h14'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
let state;let storageOkay=true;try{state=JSON.parse(localStorage.getItem('admira-v1'));if(!state||state.version!==1||!Array.isArray(state.cases))state=seed();}catch{state=seed();storageOkay=false;}
let savedRole='staff';try{savedRole=sessionStorage.getItem('admira-role')||'staff';}catch{}
let role=savedRole,page=location.hash.slice(1)||'overview',filters={year:'2026',prodi:'',region:'',status:'',search:''},programTab='Klinik',analysisTab='Prodi',lastFocus=null,importPreview=null;
const candidateId='ADM-0001';
const candidate=()=>state.cases.find(c=>c.id===candidateId);
const fmt=(d,full=true)=>d?new Intl.DateTimeFormat('id-ID',{day:'numeric',month:full?'long':'short',year:full?'numeric':undefined,hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'}).format(new Date(d))+' WIB':'Jadwal belum diumumkan';
const initials=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('');
const pill=status=>`<span class="pill ${status==='Selesai'||status==='Aktif'||status==='Disetujui'?'green':status.includes('verifikasi')||status==='Ditangani'?'blue':status.includes('perbaikan')||status==='Ditahan'?'red':'orange'}">${esc(status)}</span>`;
const btn=(label,action,style='',i='')=>`<button class="btn ${style}" data-action="${action}">${i?icon(i):''}${label}</button>`;
const empty=(title,text)=>`<div class="empty">${icon('leaf')}<h3>${title}</h3><p>${text}</p></div>`;
const printHeader=()=>`<div class="print-only"><h2>ADMIRA · ${esc(state.module)}</h2><p>DATA SIMULASI • Periode 2026 • Versi ${esc(state.contentVersion)} • Terbit ${fmt(state.now)}<br>Sumber: data latihan ADMIRA, bukan hasil penerimaan institusi.</p></div>`;
function persist(){try{localStorage.setItem('admira-v1',JSON.stringify(state));}catch{storageOkay=false;toast('Penyimpanan perangkat penuh atau tidak tersedia. Perubahan hanya bertahan di tab ini.');}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('visible'),5000);}
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.querySelector('#main')?.focus();}});
const navStaff=[['overview','grid','Ringkasan'],['followup','tasks','Tindak lanjut'],['programs','calendar','Program layanan'],['analysis','chart','Analisis'],['data','data','Mutu data']];
const navStudent=[['home','home','Beranda'],['journey','tasks','Langkah saya'],['help','help','Bantuan'],['sessions','calendar','Klinik & kegiatan'],['explore','book','Jelajahi prodi'],['access','map','Bantuan akses']];
function go(p){page=p;location.hash=p;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){const student=role==='student',nav=student?navStudent:navStaff;const allowed=[...nav.map(n=>n[0]),'notifications','account','modules'];if(!allowed.includes(page))page=student?'home':'overview';const title=nav.find(n=>n[0]===page)?.[2]||({notifications:'Pemberitahuan',account:'Pengaturan akun',modules:'Modul ADMIRA'}[page]);const activeTickets=state.tickets.filter(t=>t.status!=='Selesai').length;
$('#app').innerHTML=`<div class="shell"><div class="mobile-scrim" data-action="menu-close"></div><aside class="sidebar" aria-label="Navigasi utama"><a class="brand" href="#${student?'home':'overview'}"><svg viewBox="0 0 34 37" aria-hidden="true"><path d="M4 30 15 5h5l10 25H20l-4-12-5 12Z" stroke="none" fill="currentColor"/><circle cx="28" cy="6" r="4" fill="#f7f5ef" stroke="none"/></svg>ADMIRA</a><p class="brand-note">Setiap tahap, ada tindak lanjut.</p><div class="nav-label">${student?'RUANG CALON MAHASISWA':'RUANG PENGELOLA'}</div><nav class="nav">${nav.map(([id,i,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='followup'?`<span class="count">${state.cases.filter(c=>c.status==='Perlu tindakan'||c.status==='Perlu perbaikan').length}</span>`:''}${id==='help'&&activeTickets?`<span class="count">${activeTickets}</span>`:''}</button>`).join('')}</nav><div class="nav-sub"><div class="nav-label">PREFERENSI</div><button class="nav-item ${page==='modules'?'active':''}" data-page="modules">${icon('grid')}Modul ADMIRA</button><button class="nav-item ${page==='account'?'active':''}" data-page="account">${icon('settings')}${student?'Akun saya':'Pengaturan'}</button></div><div class="sidebar-bottom"><div class="sidebar-card"><span class="spark">${icon('leaf')}</span><strong>Penerimaan yang lebih terarah.</strong><p>Hubungkan setiap temuan dengan langkah yang berarti.</p><button data-action="guide">Baca panduan ADMIRA ${icon('arrow')}</button></div><div class="sidebar-profile"><span class="avatar dark">${student?'NP':'AR'}</span><div class="profile-copy">${student?'Nadia Putri':'Alya Rahma'}<small>${student?'Calon mahasiswa':'Petugas penerimaan'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="menu" aria-label="Buka navigasi">${icon('menu')}</button><span class="mobile-brand">ADMIRA</span><span>${student?'Ruang calon mahasiswa':'Ruang pengelola'}</span>${icon('chevron')}<span>${title}</span></div><div class="top-tools"><div class="role-switch" aria-label="Pilih ruang simulasi"><button data-role="staff" class="${!student?'active':''}">Petugas</button><button data-role="student" class="${student?'active':''}">Calon mahasiswa</button></div><button class="icon-btn" data-page="notifications" aria-label="Pemberitahuan">${icon('bell')}<span class="notification-dot"></span></button><button class="icon-btn" data-page="account" aria-label="Akun"><span class="avatar">${student?'NP':'AR'}</span></button></div></header><main id="main" class="content" tabindex="-1">${printHeader()}${content()}<footer class="footer"><span>© 2026 ADMIRA. Setiap tahap, ada tindak lanjut.</span><span>${icon('shield')} Data simulasi • Waktu demo ${fmt(state.now,false)}</span></footer></main></div><nav class="bottom-nav" aria-label="Navigasi ponsel">${(student?[['home','home','Beranda'],['journey','tasks','Langkah saya'],['help','help','Bantuan'],['account','user','Akun']]:[['overview','grid','Ringkasan'],['followup','tasks','Tindak lanjut'],['programs','calendar','Program'],['data','data','Data']]).map(([id,i,label])=>`<button class="${page===id?'active':''}" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}</button>`).join('')}</nav></div>`;
}
const intro=(eyebrow,title,desc,actions='')=>`<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="intro-actions">${actions}</div>`:''}</div>`;
const demo=()=>`<div class="demo-banner">${icon('info')}<span><strong>Ruang simulasi.</strong> Semua identitas, jadwal, dan angka adalah data latihan.${!storageOkay?' Penyimpanan perangkat tidak tersedia.':''}</span><span class="right">Periode penerimaan 2026</span></div>`;
function filterbar(search=false){const opts=(values,current,label)=>`<option value="">${label}</option>${values.map(v=>`<option ${current===v?'selected':''}>${esc(v)}</option>`).join('')}`;return `<div class="filters"><span class="filter-label">${icon('filter')}Tampilkan</span><select data-filter="year" aria-label="Tahun penerimaan"><option value="2026">Penerimaan 2026</option><option value="2025" ${filters.year==='2025'?'selected':''}>Penerimaan 2025</option></select><select data-filter="prodi" aria-label="Program studi">${opts([...new Set(state.cases.map(c=>c.prodi))],filters.prodi,'Semua program studi')}</select><select data-filter="region" aria-label="Wilayah">${opts([...new Set(state.cases.map(c=>c.region))],filters.region,'Semua wilayah')}</select>${search?`<input class="search-input" id="case-search" type="search" aria-label="Cari nama atau ID" placeholder="Cari nama atau ID pendaftaran" value="${esc(filters.search)}">`:''}<span class="updated">${icon('refresh')}Diperbarui ${fmt(state.updatedAt,false)}</span></div>`;}
function casesTable(cases,limit=Infinity){if(!cases.length)return empty('Belum ada kasus pada cakupan ini','Ubah filter untuk melihat pendaftaran lainnya.');return `<div class="table-wrap"><table class="responsive-table"><thead><tr><th>CALON MAHASISWA</th><th>PROGRAM STUDI</th><th>STATUS TUGAS</th><th>PENANGGUNG JAWAB</th><th aria-label="Tindakan"></th></tr></thead><tbody>${cases.slice(0,limit).map(c=>`<tr><td><div class="table-person"><span class="avatar">${initials(c.name)}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.id)} • ${esc(stages[c.stage])}</small></div></div></td><td data-label="Prodi">${esc(c.prodi)}</td><td>${pill(c.status)}</td><td data-label="Petugas">${esc(c.owner)}</td><td><button class="table-link" data-case="${c.id}" aria-label="Buka kasus ${esc(c.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function overview(){return renderOverview({state,filters,btn,icon,esc,pill,casesTable,filterbar,demo,fmt});}
function followup(){const cases=scopedCases(state,filters);return intro('TINDAK LANJUT','Temukan yang perlu dibantu.','Setiap kasus memiliki langkah, penanggung jawab, dan riwayat yang jelas.',btn('Tiket bantuan','tickets','secondary','help'))+demo()+filterbar(true)+`<div class="tabs">${[['','Semua kasus'],['Perlu tindakan','Perlu tindakan'],['Menunggu verifikasi','Menunggu petugas'],['Perlu perbaikan','Perlu perbaikan']].map(([v,l])=>`<button data-status="${v}" class="tab ${filters.status===v?'active':''}">${l}</button>`).join('')}</div><section class="panel queue-panel"><div class="panel-head"><div><h2>Antrean pendaftaran</h2><p>${cases.length} kasus sesuai filter • status resmi dan tugas dicatat terpisah.</p></div></div>${casesTable(cases.sort((a,b)=>new Date(a.deadline||'2099-01-01')-new Date(b.deadline||'2099-01-01')))}</section>`;}
function journeyMarkup(c){return `<ol class="journey">${stages.map((name,i)=>`<li><span class="step-number ${i<c.stage?'done':i===c.stage?'current':''}">${i<c.stage?icon('check'):i+1}</span><div><h3>${name}</h3><p>${i<c.stage?'Selesai tercatat':i===c.stage?(c.source==='Aktif'?'Selesai • mahasiswa aktif':esc(c.status)):'Belum dibuka'}</p></div></li>`).join('')}</ol>`;}
function studentHome(){return renderStudentHome({state,c:candidate(),btn,icon,esc,pill,demo,fmt,journeyMarkup});}
function studentJourney(){const c=candidate(),canSubmit=['Perlu tindakan','Perlu perbaikan'].includes(c.status);return intro('LANGKAH SAYA','Sedikit lagi, tetap terarah.','Periksa persyaratan dan status pengajuanmu pada satu tempat.',btn('Panduan cetak','print-guide','secondary','download')+btn('Kalender tenggat','download-calendar','secondary','calendar'))+demo()+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Checklist daftar ulang</h2><p>Contoh persyaratan simulasi • versi ${state.contentVersion}</p></div>${pill(c.status)}</div>${c.reason?`<div class="inline-alert">Catatan petugas: ${esc(c.reason)}</div>`:''}<div class="checklist">${['Baca ketentuan daftar ulang periode ini','Siapkan identitas dan dokumen kelulusan','Pastikan dokumen terbaca dengan jelas'].map((s,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${state.checklist?.[i]?'checked':''}><span>${s}</span></label>`).join('')}</div><div class="help-box"><strong>${icon('calendar')} ${fmt(c.deadline)}</strong><p>Jadwal dan persyaratan di halaman ini adalah simulasi, bukan ketentuan institusi.</p></div><div class="section-gap"><h3>Pengajuan berkas</h3>${c.documents.map(d=>`<div class="file-row">${icon('file')} ${esc(d.name)} • ${Math.ceil(d.size/1024)} KB<br><small>Metadata simulasi; isi berkas tidak dikirim ke server.</small></div>`).join('')}${canSubmit?`<form id="upload-form"><label class="field">Pilih berkas pengajuan<input name="document" type="file" accept=".pdf,.jpg,.jpeg,.png" required><small>PDF, JPG, atau PNG • maksimal 5 MB. Gunakan berkas contoh.</small></label><p class="error" id="upload-error" role="alert"></p><button class="btn" type="submit">${icon('file')}Kirim untuk diperiksa</button></form>`:`<p>${c.status==='Menunggu verifikasi'?'Pengajuan diterima. Kamu tidak perlu mengunggah ulang selama petugas memeriksa.':'Daftar ulang telah diverifikasi. Tunggu pembukaan tahap selanjutnya.'}</p>`}</div></section><aside class="panel"><h2>Jejak langkahmu</h2>${journeyMarkup(c)}<div class="help-box">Status diperbarui ${fmt(state.updatedAt)}.<br>Klik atau centang checklist tidak mengubah status resmi.</div><div class="section-gap">${btn('Minta bantuan','new-ticket','secondary','help')}</div></aside></div>`;}
function helpPage(){const tickets=state.tickets.filter(t=>t.caseId===candidateId);return intro('BANTUAN','Sampaikan kendalamu.','Petugas dapat membantu lebih tepat jika tahu apa yang kamu hadapi.',btn('Buat tiket bantuan','new-ticket','','plus'))+demo()+`<section class="panel"><div class="panel-head"><div><h2>Tiket saya</h2><p>Balasan dan hasil penanganan tersimpan di sini.</p></div></div>${tickets.length?tickets.map(t=>ticketRow(t)).join(''):empty('Belum ada tiket bantuan','Jika ada kendala, buat tiket melalui tombol di atas.')}</section><div class="help-box">Target simulasi respons pertama: 4 jam layanan, Senin–Jumat 08.00–16.00 WIB. Ini bukan jaminan waktu penyelesaian kendala.</div>`;}
function ticketRow(t){const c=state.cases.find(c=>c.id===t.caseId);return `<div class="list-row"><span class="avatar">${icon('help')}</span><div class="grow"><h3>${esc(t.category)} <small>• ${esc(t.id)}</small></h3><p>${esc(t.text)}</p><small>${role==='staff'?esc(c?.name)+' • ':''}${fmt(t.created)} • ${t.messages.length} balasan</small></div><div>${pill(t.status)}<br><button class="text-btn" data-ticket="${esc(t.id)}">Buka tiket ${icon('arrow')}</button></div></div>`;}
function sessionsPage(){return intro('KLINIK & KEGIATAN','Ada ruang untuk bertanya.','Pilih sesi yang sesuai dengan kebutuhanmu. Setiap slot memiliki kapasitas.')+demo()+`<div class="card-grid">${state.sessions.map(s=>{const booked=s.bookings.includes(candidateId),full=s.bookings.length>=s.capacity,closed=s.status!=='Terjadwal'||new Date(s.date)<=new Date(state.now);return `<section class="session-card"><span class="pill ${closed?'red':'green'}">${esc(s.status)}</span><h2 class="section-gap">${esc(s.title)}</h2><p class="session-date">${icon('calendar')}${fmt(s.date)}</p><p class="session-meta">${esc(s.location)}<br>Petugas: ${esc(s.owner)}<br>Slot berlangsung hingga ${esc(s.end)}</p><div class="capacity"><span style="width:${s.bookings.length/s.capacity*100}%"></span></div><p class="session-meta">${s.bookings.length} dari ${s.capacity} slot terisi ${booked?'• Kamu sudah terdaftar':''}</p>${booked?`<button class="btn secondary" data-cancel-book="${s.id}">Batalkan pemesanan</button>`:`<button class="btn" data-book="${s.id}" ${full||closed?'disabled':''}>${closed?'Sesi tidak tersedia':full?'Slot penuh':'Pesan slot konsultasi'} ${icon('arrow')}</button>`}</section>`;}).join('')}</div><div class="help-box">Kehadiran konsultasi dicatat terpisah dari status daftar ulang. Pemesanan ini berlaku dalam simulasi pada perangkat ini.</div>`;}
function programsPage(){return intro('PROGRAM LAYANAN','Layanan yang punya tindak lanjut.','Hubungkan jadwal, pelaksana, sumber daya, dan hasil layanan.',btn('Buat program','new-program','','plus'))+demo()+`<div class="tabs">${['Klinik','Register program','Tiket bantuan'].map(t=>`<button class="tab ${programTab===t?'active':''}" data-program-tab="${t}">${t}</button>`).join('')}</div>${programTab==='Klinik'?`<div class="card-grid">${state.sessions.map(s=>`<section class="session-card"><div class="panel-head"><h2>${esc(s.title)}</h2>${pill(s.status)}</div><p>${fmt(s.date)}<br>${esc(s.location)}</p><p class="session-meta">Pelaksana: ${esc(s.owner)}<br>${s.bookings.length}/${s.capacity} slot terisi</p><div class="capacity"><span style="width:${s.bookings.length/s.capacity*100}%"></span></div><button class="text-btn" data-session="${s.id}">Kelola sesi ${icon('arrow')}</button></section>`).join('')}</div>`:programTab==='Tiket bantuan'?`<section class="panel">${state.tickets.length?state.tickets.map(ticketRow).join(''):empty('Belum ada tiket','Permintaan bantuan akan tampil di sini.')}</section>`:`<section class="panel">${state.programs.map(p=>`<div class="list-row"><span class="avatar">${icon(p.module==='Jangkauan'?'map':'calendar')}</span><div class="grow"><span class="label">${esc(p.module)} • ${esc(p.id)}</span><h3>${esc(p.title)}</h3><p>${esc(p.target)}</p><small>${esc(p.owner)} • ${esc(p.date)}<br>${esc(p.resources)}</small></div><div>${pill(p.status)}<br><button class="text-btn" data-program="${p.id}">Kelola ${icon('arrow')}</button></div></div>`).join('')}</section>`}`;}
const programsInfo=[['Sistem Informasi','Pelajari hubungan teknologi, data, dan proses organisasi.','book'],['Teknik Informatika','Kenali fondasi komputasi, perangkat lunak, dan pemecahan masalah.','data'],['Manajemen','Jelajahi pengelolaan organisasi, strategi, dan kegiatan bisnis.','chart'],['Kesehatan Masyarakat','Kenali pendekatan kesehatan pada tingkat komunitas dan populasi.','users']];
function explorePage(){return intro('JELAJAHI PRODI','Kenali bidang yang kamu tuju.','Profil latihan untuk menjelajahi informasi dan mengajukan pertanyaan.')+demo()+`<div class="notice">Konten berikut adalah contoh profil simulasi. Informasi resmi baru dapat diterbitkan setelah diverifikasi pengelola prodi.</div><div class="card-grid">${programsInfo.map(([name,desc,i])=>`<section class="panel prodi-card">${icon(i)}<h2>${name}</h2><p>${desc}</p><span class="pill">Contoh konten • belum resmi</span><div class="section-gap"><button class="text-btn" data-prodi="${name}">Baca profil ${icon('arrow')}</button></div></section>`).join('')}</div>`;}
function accessPage(){return intro('BANTUAN AKSES','Langkahmu layak didampingi.','Sampaikan kebutuhan pendampingan untuk ditinjau petugas.')+demo()+`<div class="two-col"><section class="panel"><h2>Ajukan pendampingan</h2><p>Permintaan simulasi dapat berupa panduan luring, pendampingan pengisian, atau asesmen kebutuhan layanan.</p><form id="access-form"><label class="field">Jenis kebutuhan<select name="type"><option>Panduan luring / cetak</option><option>Pendampingan pengisian</option><option>Asesmen kebutuhan layanan</option></select></label><label class="field">Jelaskan kebutuhanmu<textarea name="reason" required minlength="10" maxlength="1500" placeholder="Ceritakan kebutuhan yang dapat dibantu petugas..."></textarea></label><label class="check-item"><input type="checkbox" name="consent" required><span>Saya mengizinkan petugas meninjau kebutuhan ini untuk pendampingan simulasi.</span></label><p class="login-note">Tidak ada dana, mentor, atau layanan lapangan nyata yang dijanjikan.</p><button class="btn section-gap" type="submit">Ajukan untuk ditinjau ${icon('arrow')}</button></form></section><section class="panel"><h2>Permintaan saya</h2>${state.access.filter(a=>a.caseId===candidateId).length?state.access.filter(a=>a.caseId===candidateId).map(a=>`<div class="list-row"><div><h3>${esc(a.type)}</h3>${pill(a.status)}<p>${esc(a.reason)}</p>${a.response?`<p>Catatan: ${esc(a.response)}</p>`:''}</div></div>`).join(''):empty('Belum ada permintaan','Kebutuhanmu akan dicatat untuk ditinjau petugas.')}<div class="help-box">Mentor hanya dapat ditugaskan jika tersedia, terverifikasi, dan mendapat otorisasi peserta.</div></section></div>`;}
function analysisPage(){const cases=scopedCases(state,{year:filters.year,prodi:filters.prodi,region:filters.region}),groups=[...new Set(cases.map(c=>analysisTab==='Wilayah'?c.region:c.prodi))];return intro('ANALISIS PENERIMAAN','Baca pola, tentukan langkah.','Bandingkan kelompok dengan periode, unit, dan penyebut yang jelas.',btn('Ekspor agregat','export-analysis','secondary','download'))+demo()+filterbar()+`<div class="tabs">${['Prodi','Wilayah','Siklus'].map(t=>`<button class="tab ${analysisTab===t?'active':''}" data-analysis-tab="${t}">${t}</button>`).join('')}</div>${analysisTab==='Siklus'?scenarioPage():`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Pendaftaran menurut ${analysisTab.toLowerCase()}</h2><p>Unit pendaftaran • hasil sementara • sumber data latihan</p></div></div>${groups.length?`<div class="bar-list">${groups.map(g=>{const n=cases.filter(c=>(analysisTab==='Wilayah'?c.region:c.prodi)===g).length;return `<div class="bar-item"><div class="bar-label"><span>${esc(g)}</span><strong>${n} pendaftaran</strong></div><div class="bar-track"><span style="width:${n/cases.length*100}%"></span></div></div>`;}).join('')}</div>`:empty('Belum tersedia','Ubah cakupan filter untuk melihat kelompok.')}</section><aside class="panel"><h2>Konteks sebelum kesimpulan</h2><p>Perbedaan jumlah belum menjelaskan penyebab. Periksa status sumber, cakupan periode, dan kebutuhan yang dikonfirmasi.</p><div class="help-box">${analysisTab==='Wilayah'?'Klasifikasi 3T, koordinat, dan populasi wilayah belum tersedia. Tidak ada klasifikasi yang disimpulkan dari nama daerah.':'Daya tampung belum tersedia. Keterisian kursi dan rekomendasi kuota belum dapat dihitung.'}</div><button class="text-btn section-gap" data-action="new-program">Catat rencana tindak lanjut ${icon('arrow')}</button></aside></div><section class="panel section-gap"><h2>Kelanjutan per kelompok</h2><div class="table-wrap"><table><thead><tr><th>${analysisTab.toUpperCase()}</th><th>DITERIMA / FINAL</th><th>DAFTAR ULANG / DITERIMA</th><th>AKTIF / DAFTAR ULANG</th></tr></thead><tbody>${groups.map(g=>{const m=metrics(cases.filter(c=>(analysisTab==='Wilayah'?c.region:c.prodi)===g));return `<tr><td>${esc(g)}</td><td>${m.accepted}/${m.final}</td><td>${m.registered}/${m.accepted}</td><td>${m.active}/${m.registered}</td></tr>`;}).join('')}</tbody></table></div></section>`}`;}
function scenarioPage(){return `<div class="notice">Buku skenario menggunakan asumsi aritmetis. Mengubah masukan tidak mengubah data aktual dan bukan prediksi ML.</div><div class="two-col"><section class="panel"><h2>Asumsi siklus berikutnya</h2><form id="scenario-form">${[['count','Jumlah pendaftaran',10000000],['accepted','Proporsi diterima (%)',100],['registered','Proporsi daftar ulang dari diterima (%)',100],['active','Proporsi aktif dari daftar ulang (%)',100]].map(([name,label,max])=>`<label class="field">${label}<input type="number" name="${name}" min="0" max="${max}" step="${name==='count'?'1':'0.1'}" required value="${state.scenario[name]}"></label>`).join('')}<p class="error" id="scenario-error" role="alert"></p><button class="btn" type="submit">Hitung ulang skenario ${icon('refresh')}</button></form></section><section class="metric-result"><span class="eyebrow">HASIL BERDASARKAN ASUMSI</span><h2>Perkiraan mahasiswa aktif</h2><strong class="big">${scenarioResult(state.scenario)}</strong><p>Unit pendaftaran yang diperkirakan berlanjut sampai aktif.</p><p class="formula">${state.scenario.count} × ${state.scenario.accepted}% × ${state.scenario.registered}% × ${state.scenario.active}%</p><p>Daya tampung dan data tahun pembanding belum tersedia. Hasil tidak menyatakan kapasitas institusi.</p>${btn('Ekspor skenario','export-scenario','secondary','download')}</section></div>`;}
function dataPage(){return intro('ADMIRA MUTU DATA','Angka yang bisa ditelusuri.','Periksa struktur dan konflik sebelum data diterbitkan.',btn('Riwayat perubahan','audit','secondary','clock'))+demo()+`<div class="two-col"><section class="panel"><h2>Periksa CSV penerimaan</h2><p>Pratinjau impor mandiri untuk tabel pendaftaran yang telah dipetakan. Integrasi lima sumber menunggu kamus data final.</p><form id="import-form"><label class="field">Berkas CSV<input type="file" name="csv" accept=".csv,text/csv" required><small>Titik koma (;) • UTF-8 / BOM • maksimum 2 MB • ID dipertahankan sebagai teks.</small></label><button class="btn" type="submit">${icon('data')}Periksa berkas</button><button type="button" class="text-btn" data-action="sample-csv">Unduh contoh CSV ${icon('download')}</button></form><div id="import-result">${importPreview?importResult():''}</div><div class="help-box">Publikasi demo menyimpan batch terpisah. Data latihan pada ruang utama tetap dipertahankan agar tidak tercampur dengan impor.</div></section><section class="panel"><h2>Aturan dan asal data</h2><div class="list-row"><div><h3>Identitas pendaftaran</h3><p>ID adalah teks, termasuk nol awal. Konflik ID menahan publikasi.</p></div></div><div class="list-row"><div><h3>Kunci program studi</h3><p>Gabungkan Kode_Prodi dan Tahun_Penerimaan. Nama mirip tidak digabung otomatis.</p></div></div><div class="list-row"><div><h3>Hubungan antartahap</h3><p>Baris yang tidak ditemukan belum berarti ditolak atau mengundurkan diri.</p></div></div><div class="list-row"><div><h3>Versi sumber</h3><p>Latihan ADMIRA v1.0 • diperbarui ${fmt(state.updatedAt)}.</p></div></div></section></div><section class="panel section-gap"><div class="panel-head"><div><h2>Batch yang diterbitkan</h2><p>Publikasi hanya dimungkinkan setelah seluruh pemeriksaan lulus.</p></div></div>${state.published?`<div class="list-row"><div class="grow"><h3>${esc(state.published.name)}</h3><p>${state.published.rows.length} baris valid • ${fmt(state.published.time)} • versi ${state.published.version}</p><span class="pill green">Terbit • data impor demo</span></div><button class="text-btn" data-action="export-import">Ekspor batch ${icon('download')}</button></div>`:empty('Belum ada batch diterbitkan','Periksa CSV, tinjau laporan, lalu terbitkan versi demo.')}</section>`;}
function importResult(){return `<div class="section-gap"><h3>${esc(importPreview.name)}</h3><p>${importPreview.rows.length} baris dibaca • ${importPreview.issues.length} masalah</p>${importPreview.issues.length?`<p class="error">${importPreview.issues.slice(0,20).map(esc).join('<br>')}</p>`:`<p class="pill green">Pemeriksaan struktur lulus</p><p class="login-note">Semantik kode prodi dan hubungan lima sumber memerlukan kamus data final.</p><button class="btn section-gap" data-action="publish-import">Terbitkan batch demo</button>`}</div>`;}
function modulesPage(){return intro('SATU FONDASI, ENAM MODUL','Sesuai kebutuhan. Tetap terhubung.','Pilih fokus demonstrasi. Data tugas, tiket, dan program tetap memakai sumber yang sama.')+demo()+`<div class="module-grid">${[['Alur','tasks','Kelanjutan penerimaan, checklist, dan klinik.'],['Akses','users','Permintaan pendampingan dan asesmen layanan.'],['Prodi','book','Profil bidang studi dan konsultasi.'],['Siklus','refresh','Asumsi penerimaan dan register perbaikan.'],['Jangkauan','map','Pelaksana, mitra, dan rencana kegiatan wilayah.'],['Mutu Data','data','Pemeriksaan impor dan publikasi versi.']].map(([name,i,desc])=>`<button class="module-card ${state.module===name?'selected':''}" data-module="${name}">${icon(i)}<h2>ADMIRA ${name}</h2><p>${desc}</p><span class="text-btn">${state.module===name?'Fokus saat ini':'Buka modul'} ${icon('arrow')}</span></button>`).join('')}</div><div class="help-box">Pendampingan mentor, integrasi sumber resmi, dan pengiriman eksternal belum diaktifkan. Layanan operasional memerlukan petugas, jadwal, dan sumber daya yang terverifikasi.</div>`;}
function notificationsPage(){const c=candidate();return intro('PEMBERITAHUAN','Pesan yang tetap relevan.','Status tugas, kabar layanan, dan catatan pengingat pada satu tempat.')+demo()+`<section class="panel"><h2>${role==='student'?'Pembaruan saya':'Catatan pengingat simulasi'}</h2>${role==='student'?`<div class="message"><strong>${esc(c.status)}</strong><p>${c.status==='Menunggu verifikasi'?'Berkasmu sudah diterima dan sedang diperiksa. Kamu tidak perlu mengunggah ulang.':c.source==='Daftar ulang selesai'||c.source==='Aktif'?'Daftar ulangmu sudah diverifikasi petugas. Pantau tahap selanjutnya.':'Lihat kewajiban pada Langkah saya. Pengingat tidak mengubah status resmi.'}</p><button class="text-btn" data-page="journey">Buka langkah saya ${icon('arrow')}</button></div>`:''}${state.reminders.filter(r=>role==='staff'||r.caseId===candidateId).length?state.reminders.filter(r=>role==='staff'||r.caseId===candidateId).map(r=>`<div class="list-row"><span class="avatar">${icon('bell')}</span><div class="grow"><h3>${esc(r.caseId)} • ${fmt(r.time)}</h3><p>${esc(r.reason)}</p></div>${pill(r.status)}</div>`).join(''):empty('Belum ada pengingat disimulasikan','Simulasikan dari detail kasus di ruang petugas. Tidak ada pesan eksternal yang dikirim.')}</section>`;}
function accountPage(){return intro(role==='staff'?'PENGATURAN':'AKUN SAYA','Atur ruang kerjamu.','Preferensi dan kendali waktu untuk demonstrasi ADMIRA.')+demo()+`<div class="two-col"><section class="panel"><h2>Profil simulasi</h2><div class="list-row"><span class="avatar">${role==='staff'?'AR':'NP'}</span><div><h3>${role==='staff'?'Alya Rahma':'Nadia Putri Ramadhani'}</h3><small>${role==='staff'?'Petugas penerimaan':'Calon mahasiswa • '+candidateId}</small></div></div><div class="settings-row"><div><h3>Kanal pemberitahuan</h3><p>Portal tersedia. Email dan WhatsApp belum terhubung.</p></div><span class="pill green">Portal</span></div><div class="settings-row"><div><h3>Kontak terverifikasi</h3><p>Belum tersedia pada data simulasi.</p></div><span class="pill">Belum tersedia</span></div><div class="help-box">Pemilih ruang adalah alat demo. Akun dan pembatasan akses operasional membutuhkan layanan autentikasi di server.</div></section><section class="panel"><h2>Waktu demonstrasi</h2><p>Jam simulasi saat ini: <strong>${fmt(state.now)}</strong>. Waktu perangkat tidak diubah.</p>${role==='staff'?`<form id="clock-form"><label class="field">Tanggal dan jam simulasi (WIB)<input type="datetime-local" name="time" value="${new Date(new Date(state.now).getTime()+7*3600000).toISOString().slice(0,16)}" required></label><button type="submit" class="btn secondary">Terapkan waktu demo</button></form><div class="settings-row"><div><h3>Segarkan sumber demo</h3><p>Menandai status sumber simulasi telah ditinjau ulang.</p></div>${btn('Segarkan','refresh-data','secondary','refresh')}</div><button class="text-btn section-gap" data-action="reset-confirm">Atur ulang data latihan ${icon('refresh')}</button>`:'<div class="help-box">Waktu demo dikelola petugas untuk menguji tenggat, jam tenang, dan pengingat.</div>'}</section></div>`;}
function content(){if(role==='student')return ({home:studentHome,journey:studentJourney,help:helpPage,sessions:sessionsPage,explore:explorePage,access:accessPage,notifications:notificationsPage,account:accountPage,modules:modulesPage}[page]||studentHome)();return ({overview,followup,programs:()=>programsPage()+accessReviewPanel(),analysis:analysisPage,data:dataPage,modules:modulesPage,notifications:notificationsPage,account:accountPage}[page]||overview)();}
function accessReviewPanel(){if(!state.access.length)return '';return `<section class="panel section-gap"><div class="panel-head"><div><h2>Permintaan pendampingan akses</h2><p>Kebutuhan yang diajukan peserta untuk ditinjau petugas.</p></div></div>${state.access.map(a=>`<div class="list-row"><div class="grow"><h3>${esc(a.type)}</h3><p>${esc(a.reason)}</p><small>${esc(state.cases.find(c=>c.id===a.caseId)?.name||a.caseId)}</small></div><div>${pill(a.status)}<br><button class="text-btn" data-access-review="${a.id}">Tinjau permintaan ${icon('arrow')}</button></div></div>`).join('')}</section>`;}
function modal(title,body,wide=false){lastFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>ADMIRA • ruang simulasi</p></div><button class="icon-btn" data-action="modal-close" aria-label="Tutup dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';const focus=$('#modal-root').querySelector('input,textarea,select,button');focus?.focus();}
function closeModal(){const previous=lastFocus;$('#modal-root').innerHTML='';document.body.style.overflow='';if(previous?.isConnected)previous.focus();}
function caseModal(id){const c=state.cases.find(c=>c.id===id);if(!c||role!=='staff')return;const tickets=state.tickets.filter(t=>t.caseId===id),reason=reminderEligibility(state,c);modal(esc(c.name),`<div class="two-col"><div><div class="panel"><span class="label">${esc(c.id)} • ${esc(c.prodi)}</span><h3 class="section-gap">${esc(stages[c.stage])}</h3>${pill(c.status)}<p class="section-gap">Status sumber: <strong>${esc(c.source)}</strong><br>Tenggat: ${fmt(c.deadline)}<br>Penanggung jawab: ${esc(c.owner)}</p>${c.reason?`<div class="inline-alert">${esc(c.reason)}</div>`:''}${c.documents.map(d=>`<div class="file-row">${esc(d.name)} • ${Math.ceil(d.size/1024)} KB<br>Metadata simulasi • berkas tidak tersimpan di server.</div>`).join('')}</div><div class="section-gap"><h3>Catatan bantuan</h3>${tickets.length?tickets.map(t=>`<div class="message"><strong>${esc(t.id)} • ${esc(t.category)}</strong><p>${esc(t.text)}</p><button class="text-btn" data-ticket="${t.id}">Buka tiket ${icon('arrow')}</button></div>`).join(''):'<p>Belum ada tiket terkait.</p>'}</div></div><div><form id="case-form" data-id="${id}"><label class="field">Penanggung jawab<select name="owner">${['Belum ditugaskan','Alya Rahma','Bima Prasetyo'].map(n=>`<option ${c.owner===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Simpan penugasan</button></form>${c.status==='Menunggu verifikasi'?`<div class="section-gap"><h3>Hasil pemeriksaan simulasi</h3><label class="field">Catatan / alasan<textarea id="review-reason" placeholder="Alasan wajib jika meminta perbaikan" maxlength="1000"></textarea></label><p id="review-error" class="error" role="alert"></p><div class="actions"><button class="btn" data-verify="${id}">Verifikasi selesai</button><button class="btn secondary" data-revise="${id}">Minta perbaikan</button></div></div>`:''}<div class="help-box"><h3>Pengingat</h3><p>${reason?esc(reason):'Tugas memenuhi syarat pengingat simulasi.'}</p><button class="text-btn" data-remind="${id}">Simulasikan pengingat ${icon('bell')}</button></div><div class="section-gap"><button class="text-btn" data-deadline="${id}">Ubah tenggat simulasi ${icon('calendar')}</button></div></div></div>`,true);}
function newTicket(){modal('Kami siap mendengarkan.',`<form id="ticket-form"><label class="field">Kategori kendala<select name="category"><option>Dokumen</option><option>Akses sistem</option><option>Informasi proses</option><option>Pembiayaan</option><option>Lainnya</option></select></label><label class="field">Ceritakan kendalamu<textarea name="text" placeholder="Jelaskan kendala agar petugas dapat menindaklanjuti..." required minlength="10" maxlength="2000"></textarea></label><div class="help-box">Tiket ditujukan ke unit penerimaan simulasi. Jangan masukkan data sensitif atau kontak nyata.</div><div class="modal-actions"><button class="btn" type="submit">Kirim tiket bantuan ${icon('arrow')}</button><button type="button" class="btn secondary" data-action="modal-close">Batal</button></div></form>`);}
function ticketModal(id){const t=state.tickets.find(t=>t.id===id);if(!t||role==='student'&&t.caseId!==candidateId)return;modal(`Tiket ${esc(t.id)}`,`<div class="message"><strong>${esc(t.category)} • ${pill(t.status)}</strong><p>${esc(t.text)}</p><small>${fmt(t.created)}</small></div>${t.messages.map(m=>`<div class="message response"><strong>${esc(m.actor)}</strong><p>${esc(m.text)}</p><small>${fmt(m.time)}</small></div>`).join('')}<form id="ticket-reply-form" data-id="${t.id}"><label class="field">${role==='staff'?'Respons / ringkasan penyelesaian':'Tambahkan informasi'}<textarea name="text" required minlength="5" maxlength="2000"></textarea></label>${role==='staff'?`<label class="field">Status tiket<select name="status">${['Baru','Ditangani','Menunggu calon mahasiswa','Menunggu unit lain','Selesai','Dibuka kembali'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></label>`:''}<div class="modal-actions"><button class="btn" type="submit">Simpan respons</button>${role==='student'&&t.status==='Selesai'?`<button type="button" class="btn secondary" data-reopen="${id}">Minta dibuka kembali</button>`:''}</div></form><p class="login-note">Status tiket terpisah dari status resmi penerimaan.</p>`);}
function sessionModal(id){const s=state.sessions.find(s=>s.id===id);modal(esc(s.title),`<p>${fmt(s.date)} • ${s.bookings.length}/${s.capacity} slot</p><h3>Peserta simulasi</h3>${s.bookings.length?s.bookings.map(id=>`<div class="message">${esc(state.cases.find(c=>c.id===id)?.name||id)}</div>`).join(''):'<p>Belum ada pemesanan.</p>'}<form id="session-form" data-id="${id}"><label class="field">Status sesi<select name="status">${['Terjadwal','Selesai','Dibatalkan'].map(x=>`<option ${x===s.status?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Kapasitas<input type="number" name="capacity" min="${Math.max(1,s.bookings.length)}" max="100" value="${s.capacity}" required></label><button type="submit" class="btn">Simpan sesi</button></form><div class="help-box">Pembatalan sesi membatalkan pemesanan. Status daftar ulang peserta tetap mengikuti verifikasi.</div>`);}
function programModal(id){const p=state.programs.find(p=>p.id===id);modal(esc(p.title),`<dl class="program-details"><dt>Modul</dt><dd>${esc(p.module)}</dd><dt>Sasaran</dt><dd>${esc(p.target)}</dd><dt>Pelaksana</dt><dd>${esc(p.owner)}</dd><dt>Jadwal</dt><dd>${esc(p.date)}</dd><dt>Sumber daya</dt><dd>${esc(p.resources)}</dd></dl><form id="program-form" data-id="${id}"><label class="field">Status program<select name="status">${['Usulan','Ditinjau','Disetujui','Dijadwalkan','Berjalan','Ditinjau hasilnya','Ditutup','Dibatalkan'].map(x=>`<option ${x===p.status?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Hasil dan tindak lanjut<textarea name="result" maxlength="2000">${esc(p.result)}</textarea><small>Wajib diisi sebelum program ditutup.</small></label><p class="error" id="program-error" role="alert"></p><button type="submit" class="btn">Simpan perkembangan</button></form>`);}
function newProgram(){modal('Rencanakan tindak lanjut.',`<form id="new-program-form"><label class="field">Nama program<input name="title" required minlength="5" maxlength="150"></label><label class="field">Modul<select name="module">${['Alur','Akses','Prodi','Siklus','Jangkauan','Mutu Data'].map(x=>`<option ${state.module===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Temuan dan sasaran<textarea name="target" required minlength="10" maxlength="1000"></textarea></label><label class="field">Pelaksana<select name="owner"><option>Alya Rahma</option><option>Bima Prasetyo</option></select></label><label class="field">Tanggal rencana<input type="date" name="date" required min="2026-01-01"></label><label class="field">Kebutuhan sumber daya<input name="resources" required minlength="5" maxlength="300"></label><button type="submit" class="btn">Simpan sebagai usulan ${icon('arrow')}</button></form>`);}
function download(name,text,type='text/plain;charset=utf-8'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(value){let s=String(value??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportCSV(name,headers,rows){download(name,'\uFEFF'+[['ADMIRA • DATA SIMULASI • Periode 2026 • versi 1.0'],['Source: data latihan ADMIRA',fmt(state.now)],headers,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Ekspor simulasi telah dibuat.');}
function printGuide(){modal('Panduan ringkas ADMIRA',`<div id="guide-content"><h3>Checklist kesiapan daftar ulang</h3><p>DATA SIMULASI • Periode 2026 • Versi ${esc(state.contentVersion)}<br>Terbit ${fmt(state.now)} • Sumber: konfigurasi latihan ADMIRA.</p><ol><li>Baca status dan kewajiban pada Langkah saya.</li><li>Siapkan identitas dan dokumen kelulusan contoh.</li><li>Pastikan berkas jelas, bertipe PDF/JPG/PNG, dan maksimal 5 MB.</li><li>Kirim berkas untuk pemeriksaan. Tunggu verifikasi petugas.</li><li>Gunakan tiket bantuan bila menghadapi kendala.</li></ol><p>Contoh tenggat: ${fmt(candidate().deadline)}. Jadwal ini bukan pengumuman resmi institusi.</p><p>Jam layanan simulasi: Senin–Jumat, 08.00–16.00 WIB.<br>Kanal bantuan: menu Bantuan di ADMIRA.</p><p>Versi panduan mengikuti versi konten web. Materi publik ini tidak memuat status pribadi.</p></div><div class="modal-actions">${btn('Unduh panduan','download-guide','','download')}${btn('Tutup','modal-close','secondary')}</div>`);}
const staffActions=new Set(['export-summary','export-analysis','export-scenario','publish-import','export-import','new-program','tickets','audit','refresh-data','reset-confirm','reset','sample-csv']);
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-action]');if(!target)return;try{
if(target.dataset.page){closeModal();go(target.dataset.page);return;}
if(target.dataset.role){role=target.dataset.role;try{sessionStorage.setItem('admira-role',role);}catch{}closeModal();go(role==='student'?'home':'overview');return;}
if(target.dataset.status!==undefined){filters.status=target.dataset.status;render();return;}
if(target.dataset.case){caseModal(target.dataset.case);return;}
if(target.dataset.ticket){ticketModal(target.dataset.ticket);return;}
if(target.dataset.prodi){modal(esc(target.dataset.prodi),`<span class="pill">Profil simulasi • nonresmi</span><p class="section-gap">${programsInfo.find(x=>x[0]===target.dataset.prodi)?.[1]}</p><p>Persyaratan, kurikulum, tautan institusi, dan tanggal verifikasi belum tersedia. Profil tidak menyatakan peluang kerja atau hasil seleksi.</p><div class="modal-actions">${btn('Ajukan pertanyaan','new-ticket','','help')}${btn('Lihat sesi pengenalan','goto-sessions','secondary')}</div>`);return;}
if(target.dataset.book){if(role!=='student')return;book(state,target.dataset.book,candidateId);persist();render();toast('Pemesanan berhasil. Slot konsultasi telah dicatat.');return;}
if(target.dataset.cancelBook){cancelBooking(state,target.dataset.cancelBook,candidateId);persist();render();toast('Pemesanan dibatalkan. Slot tersedia kembali.');return;}
if(target.dataset.programTab){programTab=target.dataset.programTab;render();return;}
if(target.dataset.analysisTab){analysisTab=target.dataset.analysisTab;render();return;}
if(target.dataset.module){state.module=target.dataset.module;persist();if(role==='student'){go(({Alur:'home',Akses:'access',Prodi:'explore',Siklus:'modules',Jangkauan:'sessions','Mutu Data':'modules'})[state.module]);}else{if(state.module==='Siklus')analysisTab='Siklus';if(state.module==='Jangkauan'||state.module==='Akses')programTab='Register program';go(({Alur:'overview',Akses:'programs',Prodi:'analysis',Siklus:'analysis',Jangkauan:'programs','Mutu Data':'data'})[state.module]);}toast('Fokus demonstrasi: ADMIRA '+state.module);return;}
if(target.dataset.session&&role==='staff'){sessionModal(target.dataset.session);return;}
if(target.dataset.program&&role==='staff'){programModal(target.dataset.program);return;}
if(target.dataset.accessReview&&role==='staff'){const a=state.access.find(a=>a.id===target.dataset.accessReview);if(!a)return;modal('Tinjau pendampingan',`<h3>${esc(a.type)}</h3><p>${esc(a.reason)}</p><form id="access-review-form" data-id="${a.id}"><label class="field">Status permintaan<select name="status">${['Diajukan','Ditinjau','Perlu informasi','Dirujuk','Selesai','Tidak disetujui'].map(x=>`<option ${x===a.status?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Catatan penanganan<textarea name="response" minlength="10" required maxlength="1500">${esc(a.response||'')}</textarea></label><button class="btn" type="submit">Simpan hasil peninjauan</button></form><div class="help-box">Status ini tidak menjanjikan dana atau mengubah penerimaan.</div>`);return;}
if(target.dataset.remind&&role==='staff'){const r=simulateReminder(state,target.dataset.remind);persist();closeModal();render();modal(r.status==='Simulasi'?'Pratinjau pengingat':'Pengingat ditahan',`<span class="pill ${r.status==='Simulasi'?'green':'orange'}">${r.status}</span><p class="section-gap">${esc(r.reason)}</p>${r.status==='Simulasi'?`<div class="message"><strong>Langkah berikutnya menunggumu.</strong><p>Berdasarkan pembaruan ${fmt(state.updatedAt)}, berkas daftar ulang belum tercatat selesai. Tenggat simulasi ${fmt(state.cases.find(c=>c.id===r.caseId).deadline)}. Selesaikan pengajuan atau sampaikan kendalamu melalui Bantuan.</p></div><p class="login-note">Tidak ada WhatsApp atau email yang dikirim.</p>`:''}`);return;}
if((target.dataset.verify||target.dataset.revise)&&role==='staff'){const id=target.dataset.verify||target.dataset.revise;try{transition(state,id,target.dataset.verify?'Selesai':'Perlu perbaikan','Petugas',$('#review-reason')?.value||'');persist();closeModal();render();toast(target.dataset.verify?'Daftar ulang telah diverifikasi.':'Permintaan perbaikan telah dicatat.');}catch(err){$('#review-error').textContent=err.message;}return;}
if(target.dataset.deadline&&role==='staff'){const id=target.dataset.deadline,c=state.cases.find(c=>c.id===id);modal('Perbarui tenggat simulasi',`<form id="deadline-form" data-id="${id}"><label class="field">Tenggat baru (WIB)<input type="datetime-local" name="deadline" required value="${c.deadline?new Date(new Date(c.deadline).getTime()+7*3600000).toISOString().slice(0,16):''}"></label><label class="field">Dasar perubahan<textarea name="reason" required minlength="10" maxlength="1000"></textarea></label><button class="btn" type="submit">Simpan versi tenggat</button></form>`);return;}
if(target.dataset.reopen){const t=state.tickets.find(t=>t.id===target.dataset.reopen&&t.caseId===candidateId);if(t){audit(state,'Calon mahasiswa',t.id,'Tiket dibuka kembali',t.status,'Dibuka kembali');t.status='Dibuka kembali';persist();ticketModal(t.id);render();}return;}
const action=target.dataset.action;if(!action)return;if(staffActions.has(action)&&role!=='staff'){toast('Tindakan ini tersedia di ruang petugas.');return;}
if(action.startsWith('goto-')){closeModal();go(action.slice(5));return;}
if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-scrim').classList.add('open');return;}if(action==='menu-close'){$('.sidebar').classList.remove('open');$('.mobile-scrim').classList.remove('open');return;}if(action==='modal-close'){closeModal();return;}
if(action==='new-ticket'){newTicket();return;}if(action==='new-program'){newProgram();return;}if(action==='guide'){modal('Setiap tahap, ada tindak lanjut.',`<p>ADMIRA menghubungkan status penerimaan dengan langkah yang jelas dan layanan yang dapat dilacak.</p><ol><li>Gunakan pemilih ruang di bagian atas untuk mencoba peran calon mahasiswa atau petugas.</li><li>Kirim berkas dari Langkah saya, lalu periksa di Tindak lanjut pada ruang petugas.</li><li>Coba tiket bantuan, pemesanan klinik, dan simulasi pengingat.</li><li>Pilih modul untuk melihat analisis dan program terkait.</li></ol><div class="help-box">Ini prototipe dengan penyimpanan pada browser yang sama. Semua data, akun, dan pengiriman bersifat simulasi.</div>`);return;}
if(action==='print-guide'){printGuide();return;}if(action==='download-guide'){const body=$('#guide-content').innerHTML;download('ADMIRA-Panduan-SIMULASI-v1.html',`<!doctype html><html lang="id"><meta charset="utf-8"><title>ADMIRA · Panduan simulasi</title><style>body{max-width:760px;margin:45px auto;padding:0 24px;font:16px/1.8 Arial;color:#123e3a}h1{font:42px Georgia}button{padding:12px;background:#123e3a;color:white;border:0;cursor:pointer}@media print{button{display:none}}</style><h1>ADMIRA</h1>${body}<button onclick="window.print()">Cetak panduan</button></html>`,'text/html;charset=utf-8');return;}
if(action==='tickets'){programTab='Tiket bantuan';go('programs');return;}
if(action==='download-calendar'){const c=candidate();if(!c.deadline)throw Error('Jadwal belum diumumkan.');const stamp=d=>new Date(d).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('ADMIRA-Tenggat-SIMULASI.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ADMIRA//SIMULASI//ID','BEGIN:VEVENT','UID:admira-demo-deadline-v'+(c.deadlineVersion||1),'DTSTAMP:'+stamp(state.now),'DTSTART:'+stamp(c.deadline),'DTEND:'+stamp(new Date(new Date(c.deadline).getTime()+60000)),'SUMMARY:ADMIRA - Tenggat daftar ulang SIMULASI','DESCRIPTION:Jadwal latihan ADMIRA. Bukan tenggat resmi institusi. Versi '+state.contentVersion,'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar;charset=utf-8');return;}
if(action==='export-summary'){const m=metrics(scopedCases(state,{year:filters.year,prodi:filters.prodi,region:filters.region}));exportCSV('ADMIRA-Ringkasan-SIMULASI.csv',['Metrik','Jumlah','Cakupan'],[['Pendaftaran',m.total,JSON.stringify(filters)],['Diterima',m.accepted,'Penyebut hasil final: '+m.final],['Daftar ulang',m.registered,'Penyebut diterima: '+m.accepted],['Aktif',m.active,'Penyebut daftar ulang: '+m.registered]]);return;}
if(action==='export-analysis'){const cases=scopedCases(state,{year:filters.year,prodi:filters.prodi,region:filters.region}),key=analysisTab==='Wilayah'?'region':'prodi';const groups=[...new Set(cases.map(c=>c[key]))];exportCSV('ADMIRA-Analisis-SIMULASI.csv',['Kelompok','Pendaftaran','Diterima','Hasil final','Daftar ulang','Aktif'],groups.map(g=>{const m=metrics(cases.filter(c=>c[key]===g));return [g,m.total,m.accepted,m.final,m.registered,m.active];}));return;}
if(action==='export-scenario'){exportCSV('ADMIRA-Skenario-ASUMSI.csv',['Pendaftaran asumsi','Diterima %','Daftar ulang %','Aktif %','Hasil asumsi'],[[...Object.values(state.scenario),scenarioResult(state.scenario)]]);return;}
if(action==='sample-csv'){download('ADMIRA-contoh-SIMULASI.csv','\uFEFFID_Pendaftaran;Nama;Kode_Prodi;Tahun_Penerimaan;Wilayah;Status\r\n00001;Peserta Simulasi;SI;2026;Jawa Timur;Diterima\r\n00002;Peserta Latihan;SI;2026;Jawa Tengah;Hasil belum diumumkan','text/csv;charset=utf-8');return;}
if(action==='publish-import'){if(!importPreview||importPreview.issues.length)throw Error('Selesaikan masalah impor terlebih dahulu.');state.published={name:importPreview.name,rows:importPreview.rows,time:state.now,version:(state.published?.version||0)+1};audit(state,'Petugas','CSV','Batch demo diterbitkan');persist();importPreview=null;render();toast('Batch demo diterbitkan. Data latihan utama tetap terpisah.');return;}
if(action==='export-import'){const p=state.published;if(p)exportCSV('ADMIRA-Batch-SIMULASI.csv',Object.keys(p.rows[0]),p.rows.map(Object.values));return;}
if(action==='audit'){modal('Riwayat yang dapat ditelusuri.',`<div class="audit-list">${state.audit.length?state.audit.map(a=>`<div class="audit-item"><strong>${esc(a.action)} • ${esc(a.entity)}</strong><small>${esc(a.actor)} • ${fmt(a.time)}</small>${a.before||a.after?`<p>${esc(a.before)} → ${esc(a.after)}</p>`:''}</div>`).join(''):empty('Belum ada perubahan','Tindakan simulasi akan dicatat di sini.')}</div>`);return;}
if(action==='refresh-data'){state.updatedAt=state.now;audit(state,'Petugas','Sumber latihan','Status simulasi ditinjau ulang');persist();render();toast('Kesegaran sumber demo diperbarui.');return;}
if(action==='reset-confirm'){modal('Mulai ulang simulasi?',`<p>Tugas, tiket, pemesanan, program, dan impor latihan pada browser ini akan dikembalikan ke contoh awal.</p><div class="modal-actions">${btn('Atur ulang data latihan','reset','danger')}${btn('Kembali','modal-close','secondary')}</div>`);return;}
if(action==='reset'){state=seed();importPreview=null;persist();closeModal();render();toast('Data latihan telah dikembalikan.');return;}
}catch(err){toast(err.message||'Tindakan belum berhasil. Coba lagi.');}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render();}if(e.target.dataset.check!==undefined){state.checklist??={};state.checklist[e.target.dataset.check]=e.target.checked;persist();}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='case-search'){clearTimeout(searchTimer);const value=e.target.value,pos=e.target.selectionStart;searchTimer=setTimeout(()=>{filters.search=value;render();const input=$('#case-search');input?.focus();if(input?.type==='text')input.setSelectionRange(pos,pos);},250);}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const fd=new FormData(form);try{
if(form.id==='upload-form'){if(role!=='student')return;const f=fd.get('document');if(!f||!f.size)throw Error('Pilih berkas yang berisi data.');if(!/\.(pdf|png|jpe?g)$/i.test(f.name)||!['application/pdf','image/jpeg','image/png',''].includes(f.type))throw Error('Gunakan berkas PDF, JPG, atau PNG.');if(f.size>5*1024*1024)throw Error('Ukuran berkas melebihi 5 MB.');const bytes=new Uint8Array(await f.slice(0,8).arrayBuffer());const actual=bytes[0]===0x25&&bytes[1]===0x50&&bytes[2]===0x44&&bytes[3]===0x46?'pdf':bytes[0]===0xff&&bytes[1]===0xd8?'jpg':bytes[0]===0x89&&bytes[1]===0x50&&bytes[2]===0x4e&&bytes[3]===0x47?'png':null;if(!actual||actual==='pdf'&&!/\.pdf$/i.test(f.name)||actual==='jpg'&&!/\.jpe?g$/i.test(f.name)||actual==='png'&&!/\.png$/i.test(f.name))throw Error('Isi berkas tidak sesuai format. Pilih PDF atau gambar yang valid.');transition(state,candidateId,'Menunggu verifikasi','Calon mahasiswa');candidate().documents=[{name:f.name,size:f.size,type:f.type}];persist();render();toast('Pengajuan diterima. Menunggu verifikasi petugas.');return;}
if(form.id==='ticket-form'){if(role!=='student')throw Error('Buka ruang calon mahasiswa untuk mengajukan bantuan.');const text=fd.get('text').trim();if(text.length<10)throw Error('Jelaskan kendala setidaknya 10 karakter.');const id='TKT-'+String(state.tickets.length+1).padStart(3,'0');state.tickets.unshift({id,caseId:candidateId,category:fd.get('category'),text,status:'Baru',created:state.now,messages:[]});state.reminders.filter(r=>r.caseId===candidateId&&r.status==='Dijadwalkan').forEach(r=>r.status='Dibatalkan');audit(state,'Calon mahasiswa',id,'Tiket dibuat');persist();closeModal();go('help');toast('Tiket '+id+' berhasil dibuat.');return;}
if(form.id==='ticket-reply-form'){const t=state.tickets.find(t=>t.id===form.dataset.id);if(!t||role==='student'&&t.caseId!==candidateId)throw Error('Tiket tidak dapat diakses.');const text=fd.get('text').trim();if(text.length<5)throw Error('Tuliskan respons setidaknya 5 karakter.');t.messages.push({actor:role==='staff'?'Petugas':'Calon mahasiswa',text,time:state.now});if(role==='staff')t.status=fd.get('status');audit(state,role==='staff'?'Petugas':'Calon mahasiswa',t.id,'Respons tiket');persist();closeModal();render();ticketModal(t.id);return;}
if(form.id==='access-form'){state.access.unshift({id:crypto.randomUUID(),caseId:candidateId,type:fd.get('type'),reason:fd.get('reason').trim(),status:'Diajukan',time:state.now});audit(state,'Calon mahasiswa',candidateId,'Permintaan akses diajukan');persist();render();toast('Permintaan pendampingan telah dicatat.');return;}
if(role!=='staff')throw Error('Tindakan ini memerlukan ruang petugas.');
if(form.id==='access-review-form'){const a=state.access.find(a=>a.id===form.dataset.id);if(!a)throw Error('Permintaan tidak ditemukan.');a.status=fd.get('status');a.response=fd.get('response').trim();audit(state,'Petugas',a.id,'Hasil peninjauan pendampingan',null,a.status);persist();closeModal();render();toast('Hasil peninjauan disimpan.');return;}
if(form.id==='case-form'){const c=state.cases.find(c=>c.id===form.dataset.id);audit(state,'Petugas',c.id,'Perubahan penanggung jawab',c.owner,fd.get('owner'));c.owner=fd.get('owner');persist();closeModal();render();toast('Penanggung jawab diperbarui.');return;}
if(form.id==='scenario-form'){const values=Object.fromEntries(['count','accepted','registered','active'].map(k=>[k,Number(fd.get(k))]));scenarioResult(values);state.scenario=values;audit(state,'Petugas','Siklus','Asumsi skenario diperbarui');persist();render();toast('Skenario dihitung ulang. Data aktual tetap sama.');return;}
if(form.id==='import-form'){const f=fd.get('csv');if(f.size>2*1024*1024)throw Error('Ukuran CSV maksimum 2 MB.');const raw=await f.arrayBuffer();const text=new TextDecoder('utf-8',{fatal:true}).decode(raw);const rows=parseCSV(text);importPreview={name:f.name,rows,issues:validateImport(rows)};$('#import-result').innerHTML=importResult();return;}
if(form.id==='clock-form'){const time=new Date(fd.get('time')+':00+07:00');if(!Number.isFinite(time.getTime()))throw Error('Waktu tidak valid.');state.now=time.toISOString();persist();render();toast('Waktu demo diperbarui.');return;}
if(form.id==='session-form'){const s=state.sessions.find(s=>s.id===form.dataset.id),capacity=Number(fd.get('capacity'));if(capacity<s.bookings.length||capacity<1||capacity>100)throw Error('Kapasitas harus mencukupi peserta dan maksimum 100.');const before=s.status;s.status=fd.get('status');s.capacity=capacity;if(s.status==='Dibatalkan'){s.cancelledBookings=[...s.bookings];s.bookings=[];}audit(state,'Petugas',s.id,'Sesi diperbarui',before,s.status);persist();closeModal();render();toast('Sesi diperbarui.');return;}
if(form.id==='program-form'){const p=state.programs.find(p=>p.id===form.dataset.id),status=fd.get('status'),result=fd.get('result').trim();if(['Ditutup','Ditinjau hasilnya'].includes(status)&&result.length<10)throw Error('Tuliskan hasil dan tindak lanjut minimal 10 karakter.');audit(state,'Petugas',p.id,'Perkembangan program',p.status,status);p.status=status;p.result=result;persist();closeModal();render();toast('Perkembangan program disimpan.');return;}
if(form.id==='new-program-form'){const p=Object.fromEntries(fd.entries());p.id='PRG-'+String(state.programs.length+1).padStart(3,'0');p.status='Usulan';p.result='';state.programs.unshift(p);audit(state,'Petugas',p.id,'Usulan program dibuat');persist();closeModal();programTab='Register program';go('programs');toast('Usulan program disimpan.');return;}
if(form.id==='deadline-form'){const c=state.cases.find(c=>c.id===form.dataset.id),d=new Date(fd.get('deadline')+':00+07:00');if(!Number.isFinite(d.getTime()))throw Error('Tenggat tidak valid.');audit(state,'Petugas',c.id,'Tenggat diubah: '+fd.get('reason'),c.deadline,d.toISOString());c.deadline=d.toISOString();c.deadlineVersion=(c.deadlineVersion||1)+1;state.reminders.filter(r=>r.caseId===c.id&&r.status==='Dijadwalkan').forEach(r=>r.status='Dibatalkan');persist();closeModal();render();toast('Versi tenggat diperbarui. Jadwal lama dibatalkan.');return;}
}catch(err){const errorEl=form.querySelector('.error');if(errorEl)errorEl.textContent=err.message;else toast(err.message||'Data belum dapat diproses.');}});
document.addEventListener('keydown',e=>{const dialog=$('#modal-root .modal');if(!dialog)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const items=[...dialog.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next!==page){page=next;closeModal();render();}});
window.addEventListener('storage',e=>{if(e.key==='admira-v1'&&e.newValue){try{const next=JSON.parse(e.newValue);if(next.version===1){state=next;closeModal();render();toast('Data diperbarui dari tab lain.');}}catch{}}});
render();
